    13	Buffer *initBuffer(size_t bufSize, size_t blkSize, Buffer *buf)
    14	{
    15		if (buf == NULL || blkSize == 0)
    16			return NULL;
    17	
    18		/* Every block occupies blkSize + 1 bytes of the buffer: one leading byte
    19		 * flags whether the slot is available, the remaining blkSize bytes hold
    20		 * the block payload that is handed out to the caller. */
    21		buf->numIO = 0;
    22		buf->bufSize = bufSize;
    23		buf->blkSize = blkSize;
    24		buf->numAllBlk = bufSize / (blkSize + 1);
    25		buf->numFreeBlk = buf->numAllBlk;
    26	
    27		if ((buf->data = (unsigned char *)malloc(bufSize)) == NULL)
    28		{
    29			perror("Buffer Initialization Failed!\n");
    30			return NULL;
    31		}
    32	
    33		memset(buf->data, 0, bufSize); /* every slot starts out BLOCK_AVAILABLE */
    34	
    35		return buf;
    36	}
    37	
    38	void freeBuffer(Buffer *buf)
    39	{
    40		free(buf->data);
    41	}
    42	
    43	unsigned char *getNewBlockInBuffer(Buffer *buf)
    44	{
    45		unsigned char *blkPtr;
    46		size_t i;
    47	
    48		if (buf == NULL || buf->numFreeBlk == 0)
    49		{
    50			perror("Buffer Overflows!\n");
    51			return NULL;
    52		}
    53	
    54		/* Scan the slots for the first available one, mark it used and return
    55		 * the payload address (the byte right after the availability flag). */
    56		for (i = 0; i < buf->numAllBlk; i++)
    57		{
    58			blkPtr = buf->data + i * (buf->blkSize + 1);
    59			if (*blkPtr == BLOCK_AVAILABLE)
    60			{
    61				*blkPtr = BLOCK_UNAVAILABLE;
    62				buf->numFreeBlk--;
    63				return blkPtr + 1;
    64			}
    65		}
    66	
    67		perror("Buffer Overflows!\n");
    68		return NULL;
    69	}
