   105	
   106	/* State of the hash partition writer.
   107	 *
   108	 * One block per bucket is kept in the buffer (BUCKET_NUM = 6 blocks, which
   109	 * still leaves room for the block that is being scanned). A partition block
   110	 * looks like
   111	 *
   112	 *   [ number of tuples : 4 ][ up to HASH_PER_BLK tuples : 8 each ] ...
   113	 *   ... [ address of the next block of this bucket : 4 (last 4 bytes) ]
   114	 *
   115	 * Bucket b of the relation starting at addr is chained from block
   116	 * addr + b * (OFFSET / BUCKET_NUM), which keeps the buckets of R and of S
   117	 * inside their own OFFSET-sized address range.
   118	 */
   119	static unsigned char *hashBlk[BUCKET_NUM] = { NULL };
   120	static int hashCnt[BUCKET_NUM] = { 0 };
   121	static unsigned int hashAddr[BUCKET_NUM] = { 0 };
   122	
   123	static unsigned int bucketStride()
   124	{
   125		return OFFSET / BUCKET_NUM;
   126	}
   127	
   128	/* Flush one bucket block, chaining it to next. */
   129	static void flushHashBlock(Buffer *buf, int b, unsigned int next)
   130	{
   131		memcpy(hashBlk[b], &hashCnt[b], PTR_SIZE);
   132		memcpy(hashBlk[b] + buf->blkSize - PTR_SIZE, &next, PTR_SIZE);
   133		writeBlockToDisk(hashBlk[b], hashAddr[b], buf);
   134		hashBlk[b] = NULL;
   135		hashCnt[b] = 0;
   136	}
   137	
   138	void pushHashToWrite(Buffer *buf, Relation *R, unsigned int addr, bool reset, bool push)
   139	{
   140		if (reset)
   141		{
   142			/* Forget every pending block: the buffer they belong to may be gone. */
   143			for (int b = 0; b < BUCKET_NUM; b++)
   144			{
   145				hashBlk[b] = NULL;
   146				hashCnt[b] = 0;
   147				hashAddr[b] = addr + b * bucketStride();
   148			}
   149			return;
   150		}
   151	
   152		if (buf == NULL)
   153			return;
   154	
   155		if (R != NULL)
   156		{
   157			int b = R->attr1 % BUCKET_NUM; /* hash function: key mod BUCKET_NUM */
   158	
   159			if (hashBlk[b] == NULL)
   160			{
   161				if ((hashBlk[b] = getNewBlockInBuffer(buf)) == NULL)
   162					return;
   163				memset(hashBlk[b], 0, buf->blkSize);
   164				hashCnt[b] = 0;
   165			}
   166	
   167			if (hashCnt[b] >= HASH_PER_BLK)
   168			{
   169				/* Bucket block is full: chain it to the next block of the bucket. */
   170				unsigned int next = hashAddr[b] + 1;
   171				flushHashBlock(buf, b, next);
   172				hashAddr[b] = next;
   173	
   174				if ((hashBlk[b] = getNewBlockInBuffer(buf)) == NULL)
   175					return;
   176				memset(hashBlk[b], 0, buf->blkSize);
   177				hashCnt[b] = 0;
   178			}
   179	
   180			memcpy(hashBlk[b] + PTR_SIZE + hashCnt[b] * 2 * PTR_SIZE, &R->attr1, PTR_SIZE);
   181			memcpy(hashBlk[b] + PTR_SIZE + hashCnt[b] * 2 * PTR_SIZE + PTR_SIZE, &R->attr2, PTR_SIZE);
   182			hashCnt[b]++;
   183			memcpy(hashBlk[b], &hashCnt[b], PTR_SIZE);
   184		}
   185	
   186		if (push)
   187		{
   188			/* Write the last block of every bucket. Empty buckets get an empty
   189			 * block so that every bucket chain can be opened unconditionally. */
   190			for (int b = 0; b < BUCKET_NUM; b++)
   191			{
   192				if (hashBlk[b] == NULL)
   193				{
   194					if ((hashBlk[b] = getNewBlockInBuffer(buf)) == NULL)
   195						continue;
   196					memset(hashBlk[b], 0, buf->blkSize);
   197					hashCnt[b] = 0;
   198				}
   199				flushHashBlock(buf, b, 0);
   200			}
   201		}
   202	}
   203	
   204	int readHashFromBlock(unsigned char *blk, Relation *R)
   205	{
   206		int num = 0;
   207	
   208		if (blk == NULL || R == NULL)
   209			return 0;
   210	
   211		/* The first 4 bytes of a partition block hold the number of tuples. */
   212		memcpy(&num, blk, PTR_SIZE);
   213		if (num < 0)
   214			num = 0;
   215		if (num > HASH_PER_BLK)
   216			num = HASH_PER_BLK;
   217	
   218		for (int i = 0; i < num; i++)
   219		{
   220			memcpy(&R[i].attr1, blk + PTR_SIZE + i * 2 * PTR_SIZE, PTR_SIZE);
   221			memcpy(&R[i].attr2, blk + PTR_SIZE + i * 2 * PTR_SIZE + PTR_SIZE, PTR_SIZE);
   222		}
   223	
   224		return num;
   225	}
