   205	{
   206		int num = 0;
   207	
   208		if (blk == NULL || R == NULL)
   209			return 0;
   210	
   211		/* The first 4 bytes of a partition block hold the number of tuples. */
   212		memcpy(&num, blk, PTR_SIZE);
   213		if (num < 0)
   214			num = 0;
   215		if (num > HASH_PER_BLK)
   216			num = HASH_PER_BLK;
   217	
   218		for (int i = 0; i < num; i++)
   219		{
   220			memcpy(&R[i].attr1, blk + PTR_SIZE + i * 2 * PTR_SIZE, PTR_SIZE);
   221			memcpy(&R[i].attr2, blk + PTR_SIZE + i * 2 * PTR_SIZE + PTR_SIZE, PTR_SIZE);
   222		}
   223	
   224		return num;
   225	}
