//
// Created by zl on 2023/12/11.
//

#include <string.h>
#include <iostream>
#include "blkio.h"
#include "file.h"

using namespace std;

/* State of the buffered result writer.
 *
 * Result tuples are accumulated in a single block of the buffer. As soon as
 * the next tuple would no longer fit (the last PTR_SIZE bytes of every block
 * are reserved for the address of the following block) the block is flushed
 * to disk and a fresh one is taken from the buffer.
 *
 * pushToWrite(buf, NULL, 0, addr, true)        -> start a new result at addr
 * pushToWrite(buf, tuple, sizeof(tuple), addr) -> append one tuple
 * pushToWrite(buf, NULL, 0, addr, false, true) -> flush the last block
 */
static unsigned char *writeBlk = NULL; /* block currently being filled */
static size_t writeOff = 0;            /* bytes already used in writeBlk */
static unsigned int writeAddr = 0;     /* disk address of writeBlk */

void pushToWrite(Buffer *buf, unsigned char *source, size_t size, unsigned int addr, bool reset, bool push)
{
	if (reset)
	{
		/* The buffer the previous result was written with may already be
		 * gone, so never touch writeBlk here - just forget about it. */
		writeBlk = NULL;
		writeOff = 0;
		writeAddr = addr;
		return;
	}

	if (buf == NULL)
		return;

	const size_t capacity = buf->blkSize - PTR_SIZE; /* usable payload bytes */

	if (source != NULL && size > 0)
	{
		if (writeBlk == NULL)
		{
			if ((writeBlk = getNewBlockInBuffer(buf)) == NULL)
				return;
			memset(writeBlk, 0, buf->blkSize);
			writeOff = 0;
		}

		if (writeOff + size > capacity)
		{
			/* Full: chain this block to the next one and flush it. */
			unsigned int next = writeAddr + 1;
			memcpy(writeBlk + buf->blkSize - PTR_SIZE, &next, PTR_SIZE);
			writeBlockToDisk(writeBlk, writeAddr, buf);
			writeAddr = next;

			if ((writeBlk = getNewBlockInBuffer(buf)) == NULL)
			{
				writeOff = 0;
				return;
			}
			memset(writeBlk, 0, buf->blkSize);
			writeOff = 0;
		}

		memcpy(writeBlk + writeOff, source, size);
		writeOff += size;
	}

	if (push && writeBlk != NULL)
	{
		/* Last block of the result: the next-block address stays 0. */
		unsigned int next = 0;
		memcpy(writeBlk + buf->blkSize - PTR_SIZE, &next, PTR_SIZE);
		writeBlockToDisk(writeBlk, writeAddr, buf);
		writeAddr++;
		writeBlk = NULL;
		writeOff = 0;
	}
}

void readTuplesFromBlock(unsigned char *blk, Relation *R)
{
	if (blk == NULL || R == NULL)
		return;

	/* A relation block stores TUPLE_PER_BLK tuples of two 4-byte integers,
	 * followed by the address of the next block of the relation. */
	for (int i = 0; i < TUPLE_PER_BLK; i++)
	{
		memcpy(&R[i].attr1, blk + i * 2 * PTR_SIZE, PTR_SIZE);
		memcpy(&R[i].attr2, blk + i * 2 * PTR_SIZE + PTR_SIZE, PTR_SIZE);
	}
}

void output(Buffer *buf, unsigned int addr, int attr1, int attr2, int attr3)
