/* State of the hash partition writer.
 *
 * One block per bucket is kept in the buffer (BUCKET_NUM = 6 blocks, which
 * still leaves room for the block that is being scanned). A partition block
 * looks like
 *
 *   [ number of tuples : 4 ][ up to HASH_PER_BLK tuples : 8 each ] ...
 *   ... [ address of the next block of this bucket : 4 (last 4 bytes) ]
 *
 * Bucket b of the relation starting at addr is chained from block
 * addr + b * (OFFSET / BUCKET_NUM), which keeps the buckets of R and of S
 * inside their own OFFSET-sized address range.
 */
static unsigned char *hashBlk[BUCKET_NUM] = { NULL };
static int hashCnt[BUCKET_NUM] = { 0 };
static unsigned int hashAddr[BUCKET_NUM] = { 0 };

static unsigned int bucketStride()
{
	return OFFSET / BUCKET_NUM;
}

/* Flush one bucket block, chaining it to next. */
static void flushHashBlock(Buffer *buf, int b, unsigned int next)
{
	memcpy(hashBlk[b], &hashCnt[b], PTR_SIZE);
	memcpy(hashBlk[b] + buf->blkSize - PTR_SIZE, &next, PTR_SIZE);
	writeBlockToDisk(hashBlk[b], hashAddr[b], buf);
	hashBlk[b] = NULL;
	hashCnt[b] = 0;
}

void pushHashToWrite(Buffer *buf, Relation *R, unsigned int addr, bool reset, bool push)
{
	if (reset)
	{
		/* Forget every pending block: the buffer they belong to may be gone. */
		for (int b = 0; b < BUCKET_NUM; b++)
		{
			hashBlk[b] = NULL;
			hashCnt[b] = 0;
			hashAddr[b] = addr + b * bucketStride();
		}
		return;
	}

	if (buf == NULL)
		return;

	if (R != NULL)
	{
		int b = R->attr1 % BUCKET_NUM; /* hash function: key mod BUCKET_NUM */

		if (hashBlk[b] == NULL)
		{
			if ((hashBlk[b] = getNewBlockInBuffer(buf)) == NULL)
				return;
			memset(hashBlk[b], 0, buf->blkSize);
			hashCnt[b] = 0;
		}

		if (hashCnt[b] >= HASH_PER_BLK)
		{
			/* Bucket block is full: chain it to the next block of the bucket. */
			unsigned int next = hashAddr[b] + 1;
			flushHashBlock(buf, b, next);
			hashAddr[b] = next;

			if ((hashBlk[b] = getNewBlockInBuffer(buf)) == NULL)
				return;
			memset(hashBlk[b], 0, buf->blkSize);
			hashCnt[b] = 0;
		}

		memcpy(hashBlk[b] + PTR_SIZE + hashCnt[b] * 2 * PTR_SIZE, &R->attr1, PTR_SIZE);
		memcpy(hashBlk[b] + PTR_SIZE + hashCnt[b] * 2 * PTR_SIZE + PTR_SIZE, &R->attr2, PTR_SIZE);
		hashCnt[b]++;
		memcpy(hashBlk[b], &hashCnt[b], PTR_SIZE);
	}

	if (push)
	{
		/* Write the last block of every bucket. Empty buckets get an empty
		 * block so that every bucket chain can be opened unconditionally. */
		for (int b = 0; b < BUCKET_NUM; b++)
		{
			if (hashBlk[b] == NULL)
			{
				if ((hashBlk[b] = getNewBlockInBuffer(buf)) == NULL)
					continue;
				memset(hashBlk[b], 0, buf->blkSize);
				hashCnt[b] = 0;
			}
			flushHashBlock(buf, b, 0);
		}
	}
}

int readHashFromBlock(unsigned char *blk, Relation *R)
{
	int num = 0;

	if (blk == NULL || R == NULL)
		return 0;

	/* The first 4 bytes of a partition block hold the number of tuples. */
	memcpy(&num, blk, PTR_SIZE);
	if (num < 0)
		num = 0;
	if (num > HASH_PER_BLK)
		num = HASH_PER_BLK;

	for (int i = 0; i < num; i++)
	{
		memcpy(&R[i].attr1, blk + PTR_SIZE + i * 2 * PTR_SIZE, PTR_SIZE);
		memcpy(&R[i].attr2, blk + PTR_SIZE + i * 2 * PTR_SIZE + PTR_SIZE, PTR_SIZE);
	}

	return num;
}

