 * attribute breaks ties so that the produced order is deterministic. */
static bool tupleLess(const Relation &a, const Relation &b)
{
	if (a.attr1 != b.attr1)
		return a.attr1 < b.attr1;
	return a.attr2 < b.attr2;
}

/* One sorted run while it takes part in the final merge. Exactly one block of
 * every run is kept in the buffer, which is what makes the merge a multi-way
 * merge that fits into M blocks: (number of runs) + 1 output block. */
struct Run
{
	unsigned char *blk;            /* block of the run held in the buffer */
	Relation tuple[TUPLE_PER_BLK]; /* the tuples stored in that block */
	int cnt;                       /* number of valid tuples in the block */
	int pos;                       /* next tuple of the block to consume */
	unsigned int next;             /* address of the next block of the run */
};

/* Read one block of a run into the buffer and decode it. */
static bool loadRunBlock(Buffer *buf, Run &run, unsigned int addr)
{
	if ((run.blk = readBlockFromDisk(addr, buf)) == NULL)
		return false;

	readTuplesFromBlock(run.blk, run.tuple);

	run.cnt = 0;
	while (run.cnt < TUPLE_PER_BLK && run.tuple[run.cnt].attr1 != 0)
		run.cnt++; /* 0 marks an unused tuple slot */
	run.pos = 0;
	memcpy(&run.next, run.blk + buf->blkSize - PTR_SIZE, PTR_SIZE);

	return true;
}

/* Whether the head of the run still holds an unconsumed tuple. */
static bool runHasTuple(const Run &run)
{
	return run.blk != NULL && run.pos < run.cnt;
}

/* Release an exhausted block and pull the next block of the run in, so that
 * the head of the run is a tuple again (unless the run is over). */
static bool refillRun(Buffer *buf, Run &run)
{
	while (run.blk != NULL && run.pos >= run.cnt)
	{
		unsigned int next = run.next;

		freeBlockInBuffer(run.blk, buf);
		run.blk = NULL;
		run.cnt = run.pos = 0;

		if (next == 0) /* the chain of the run ends here */
			break;
		if (!loadRunBlock(buf, run, next))
			return false;
	}

	return true;
}

/* Two-pass multi-way merge sort of R (choice == SORT_R) or S (choice == SORT_S)
 * on the first attribute.
 *
 * pass 1: every segment of M consecutive blocks is sorted in main memory and
 *         written back as a sorted run,
 * pass 2: the heads of all runs are merged into the globally sorted relation.
 *
 * The sorted relation is left on the disk as a chain of blocks starting at
 * MERGE_R_RET_ADDR / MERGE_S_RET_ADDR. The return value is the number of I/O's
 * performed by the sort, or -1 on failure.
 */
int mergeSort(Buffer *buf, bool choice)
{
	if (buf == NULL)
		return -1;

	const unsigned int srcAddr = (choice == SORT_R) ? R_ADDR : S_ADDR;
	const int srcBlkNum = (choice == SORT_R) ? R_BLK_NUM : S_BLK_NUM;
	const unsigned int segAddr = (choice == SORT_R) ? MERGE_R_SEG_ADDR : MERGE_S_SEG_ADDR;

	int M = (int)buf->numAllBlk; /* blocks available in the buffer */
	if (M > MAX_BLK_IN_BUF)
		M = MAX_BLK_IN_BUF;
	if (M < 2)
		return -1;

	const int segNum = (srcBlkNum + M - 1) / M; /* number of sorted runs */
	const unsigned long startIO = buf->numIO;

	Relation seg[MAX_BLK_IN_BUF * TUPLE_PER_BLK]; /* one segment in memory */
	Relation tuples[TUPLE_PER_BLK];

	/* ---------------- pass 1: generate the sorted runs ---------------- */
	for (int s = 0; s < segNum; s++)
	{
		int num = 0; /* tuples of the current segment */

		/* Read the (at most) M blocks of the segment. Every block is decoded
		 * and released right away, so the buffer never runs out of blocks. */
		for (int i = 0; i < M && s * M + i < srcBlkNum; i++)
		{
			unsigned char *blk = readBlockFromDisk(srcAddr + s * M + i, buf);
			if (blk == NULL)
				return -1;

			readTuplesFromBlock(blk, tuples);
			for (int j = 0; j < TUPLE_PER_BLK; j++)
				if (tuples[j].attr1 != 0) /* 0 marks an unused tuple slot */
					seg[num++] = tuples[j];

			freeBlockInBuffer(blk, buf);
		}

		/* Sort the segment in main memory ... */
		sort(seg, seg + num, tupleLess);

		/* ... and write it back as run number s. Every run is a chain of its
		 * own, which is why consecutive runs are M blocks apart on the disk. */
		pushToWrite(buf, NULL, 0, segAddr + s * M, true);
		for (int i = 0; i < num; i++)
			pushToWrite(buf, (unsigned char *)&seg[i], sizeof(Relation), segAddr + s * M);
		pushToWrite(buf, NULL, 0, segAddr + s * M, false, true);
	}

	return (int)(buf->numIO - startIO);
}

