#include <iostream>
#include "select.h"
#include "file.h"
#include "blkio.h"

using namespace std;

/* The two selection conditions of the lab:
 *   select * from R where R.A = 40
 *   select * from S where S.C = 60
 */
#define SELECT_R_KEY 40
#define SELECT_S_KEY 60

/* Linear search based selection. Both relations are scanned block by block;
 * only one block of the relation and one block of the result are kept in the
 * buffer at a time, so the selection needs two blocks of the buffer.
 *
 * The selected tuples are written to the chain of blocks starting at
 * SELECT_RET_ADDR. The return value is the number of selected tuples,
 * or -1 on failure.
 */
int select(Buffer *buf)
{
	if (buf == NULL)
		return -1;

	Relation tuples[TUPLE_PER_BLK];
	int num = 0;

	/* Both scans append to the same result, so the writer is reset once. */
	pushToWrite(buf, NULL, 0, SELECT_RET_ADDR, true);

	/* ---------------- select * from R where R.A = 40 ---------------- */
	cout << "select * from R where R.A = " << SELECT_R_KEY << ":" << endl;

	for (int i = 0; i < R_BLK_NUM; i++)
	{
		unsigned char *blk = readBlockFromDisk(R_ADDR + i, buf);
		if (blk == NULL)
			return -1;

		readTuplesFromBlock(blk, tuples);
		freeBlockInBuffer(blk, buf);

		for (int j = 0; j < TUPLE_PER_BLK; j++)
		{
			if (tuples[j].attr1 != SELECT_R_KEY)
				continue;

			cout << "(" << tuples[j].attr1 << ", " << tuples[j].attr2 << ")" << endl;
			pushToWrite(buf, (unsigned char *)&tuples[j], sizeof(Relation), SELECT_RET_ADDR);
			num++;
		}
	}

	return num;
}

