#define SELECT_R_KEY 40
#define SELECT_S_KEY 60

/* Linear search based selection. Both relations are scanned block by block;
 * only one block of the relation and one block of the result are kept in the
 * buffer at a time, so the selection needs two blocks of the buffer.
 *
 * The selected tuples are written to the chain of blocks starting at
 * SELECT_RET_ADDR. The return value is the number of selected tuples,
 * or -1 on failure.
 */
int select(Buffer *buf)
