	if (buf == NULL)
		return -1;

	Relation tuples[TUPLE_PER_BLK];
	int num = 0;

	/* Both scans append to the same result, so the writer is reset once. */
	pushToWrite(buf, NULL, 0, SELECT_RET_ADDR, true);

	/* ---------------- select * from R where R.A = 40 ---------------- */
