	for (int i = 0; i < R_BLK_NUM; i++)
	{
		unsigned char *blk = readBlockFromDisk(R_ADDR + i, buf);
		if (blk == NULL)
			return -1;

		readTuplesFromBlock(blk, tuples);
		freeBlockInBuffer(blk, buf);

		for (int j = 0; j < TUPLE_PER_BLK; j++)
		{
			if (tuples[j].attr1 != SELECT_R_KEY)
				continue;

			cout << "(" << tuples[j].attr1 << ", " << tuples[j].attr2 << ")" << endl;
			pushToWrite(buf, (unsigned char *)&tuples[j], sizeof(Relation), SELECT_RET_ADDR);
