#include <iostream>
#include <string.h>
#include "project.h"
#include "file.h"
#include "blkio.h"
#include "mergeSort.h"

using namespace std;

/* Projection with duplicate elimination:
 *
 *   select distinct A from R
 *
 * R is first sorted on A, which brings equal values of A next to each other;
 * a single scan of the sorted relation then keeps one tuple per group. Only
 * one block of the sorted relation and one block of the result are needed in
 * the buffer at a time.
 *
 * The projected values are written to the chain of blocks starting at
 * PROJECT_RET_ADDR. The return value is the number of distinct values of A,
 * or -1 on failure.
 */
int project(Buffer *buf)
{
	if (buf == NULL)
		return -1;

	/* --------- preparation: sort R so that duplicates become adjacent --------- */
	if (mergeSort(buf, SORT_R) < 0)
		return -1;

	pushToWrite(buf, NULL, 0, PROJECT_RET_ADDR, true);

	cout << "select distinct A from R:" << endl;

	return 0;
}

