//
// Created by zl on 2023-12-12.
//

#include <iostream>
#include <math.h>
#include "join.h"
#include "file.h"
#include "blkio.h"

using namespace std;

/* Number of blocks the buffer can hold at the same time, i.e. M. */
#define MAX_BLK_IN_BUF (BUF_SIZE / (BLK_SIZE + 1))

/* Block nested loop join of R and S on R.A = S.C.
 *
 * R is the outer relation and is read in batches of M - 1 blocks; the last
 * block of the buffer is used for the block of S that is currently probed
 * against the batch, respectively for the block of the result that is being
 * filled. Every batch of R therefore causes one complete scan of S.
 *
 * The joined tuples (A, B, D) are written to the chain of blocks starting at
 * NLJ_RET_ADDR. The return value is the number of joined tuples, or -1 on
 * failure.
 */
int nestedLoopJoin(Buffer *buf)
{
	if (buf == NULL)
		return -1;

	int M = (int)buf->numAllBlk;
	if (M > MAX_BLK_IN_BUF)
		M = MAX_BLK_IN_BUF;
	if (M < 2)
		return -1;

	const int outerBlkNum = M - 1; /* blocks of R buffered at the same time */

	Relation outer[(MAX_BLK_IN_BUF - 1) * TUPLE_PER_BLK]; /* the current batch */
	Relation tuples[TUPLE_PER_BLK];

	cout << "select R.A, R.B, S.D from R, S where R.A = S.C (nested loop join):" << endl;

	pushToWrite(buf, NULL, 0, NLJ_RET_ADDR, true);

	for (int base = 0; base < R_BLK_NUM; base += outerBlkNum)
	{
		/* ---- outer scan: fill the buffer with the next M - 1 blocks of R ---- */
		int outerNum = 0;

		for (int i = 0; i < outerBlkNum && base + i < R_BLK_NUM; i++)
		{
			unsigned char *blk = readBlockFromDisk(R_ADDR + base + i, buf);
			if (blk == NULL)
				return -1;

			readTuplesFromBlock(blk, tuples);
			freeBlockInBuffer(blk, buf);

			for (int j = 0; j < TUPLE_PER_BLK; j++)
				if (tuples[j].attr1 != 0) /* 0 marks an unused tuple slot */
					outer[outerNum++] = tuples[j];
		}
	}

	return 0;
}

